import sys

def digit_sum(x):
    total = 0
    while x > 0:
        total += x % 10
        x //= 10
    return total

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])
    S = int(data[2])

    for i in range(M, N - 1, -1):
        if digit_sum(i) == S:
            print(i)
            return

    print(-1)

if __name__ == "__main__":
    main()
